{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana maximum allowable rent increase","requirement":"A landlord may raise rent by no more than the lesser of 3% of current rent or 80% of the CPI change each year; the maximum for September 1, 2026 through August 31, 2027 is 2.87%. A monthly registration pass-through fee is capped at $50 per unit.","key_value":"2.87% for Sept 1, 2026–Aug 31, 2027; cap is lesser of 3% of current rent or 80% of CPI change","coverage_conditions":null,"applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":"Tenant may file a petition to review a rent increase above the maximum; a landlord charging a pass-through fee above $50 must reimburse the overpayment.","effective_date":"2026-09-01","valid_through":"2027-08-31","citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"2.87 percent is the maximum allowable rent increase for the period of September 1, 2026 through August 31, 2027.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana just cause eviction and relocation assistance","requirement":"A landlord must have a valid reason to evict, such as nonpayment of rent, breaking the lease, or the landlord moving into the property; for certain reasons the landlord may have to help pay the tenant's moving costs.","key_value":null,"coverage_conditions":null,"applicability":{"conditions":[],"per_tenancy":"Valid cause required, such as nonpayment of rent, lease violation or owner move-in; relocation assistance may be owed for certain causes.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
